#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MiniCut Patch 31: THE EFFECT PACK (158 new media effects)   (needs patch 30)
==========================================================================
New effect groups in the Effects tab: Color, Opacity, Glitch, VHS, Background, Repeat, Particle, 3D object, Wipes & shatter,
Shake & transform, Strokes & shadows, Distortion & warp, Procedural, Move, Blur, Lens, Water & glass, Ink & paint.
 * every effect explains itself (tooltip in the gallery and a line in its card) and can be found by searching (also by other
   names, for example "vhs", "chroma key", "pixel sort", "kaleidoscope")
 * effects that change by themselves use the time of the clip; wipes can be set by hand (Progress) or run by themselves
   (Run by itself = seconds, Start after, Reverse)
 * the pack lives in the new folder minicut/render/fxpack: a module that cannot be loaded never stops MiniCut or the other modules

    python apply_31_effect_pack.py            install
    python apply_31_effect_pack.py --check    preview only
    python apply_31_effect_pack.py --revert   undo last install
    python apply_31_effect_pack.py --force    install over local edits
"""
import datetime, hashlib, json, os, py_compile, shutil, subprocess, sys

